insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_music2_v1'
from (values
('117.311.c.1.A',3,'A student listens to two professional recordings of the same piece, one orchestral and one for band, and notes similarities and differences. What is she doing?','["Comparing and contrasting exemplary musical examples", "Tuning an instrument", "Selling tickets", "Copying a score"]'::jsonb,0,'Comparison uses recordings as models.','original'),
('117.311.c.1.A',3,'Which listening task best compares two live performances?','["Naming the printer", "Noting differences in tone, balance and interpretation", "Rating the lobby", "Counting the audience"]'::jsonb,1,'Compare musical qualities.','original'),
('117.311.c.1.B',3,'A singer reads a melody in solfège, then compares it with the harmony part sung by another section. What is she comparing?','["Ticket sections", "Stage doors", "Melodic and harmonic parts", "Costume colors"]'::jsonb,2,'She contrasts melody with harmony.','original'),
('117.311.c.1.B',3,'Which part usually carries the main tune in a choral piece?','["The page number", "The accompaniment only", "The silence", "The melody"]'::jsonb,3,'The melody is the featured line.','original'),
('117.311.c.1.C',3,'The interval from C up to G is a ___.','["Perfect fifth", "Octave", "Minor third", "Major second"]'::jsonb,0,'C to G spans five letter names.','original'),
('117.311.c.1.C',3,'A minor triad differs from a major triad because its third is what?','["Removed", "Lowered by a half step", "Doubled", "Raised by a whole step"]'::jsonb,1,'Minor chords have a minor third.','original'),
('117.311.c.1.D',3,'Compare 3/4 and 6/8. What is a key difference?','["6/8 has two sharps", "Both are asymmetrical", "3/4 is simple meter and 6/8 is compound meter", "3/4 has no beat"]'::jsonb,2,'Simple meters divide the beat in two; compound in three.','original'),
('117.311.c.1.D',3,'A student counts 1-la-li, 2-la-li in a measure. This is a counting system for which meter?','["Silent", "Simple duple", "Free", "Compound"]'::jsonb,3,'Three subdivisions per beat signal compound meter.','original'),
('117.311.c.1.E',3,'A song that follows A-B-A-C-A form is a ___.','["Rondo", "Ternary", "Binary", "Strophic"]'::jsonb,0,'A rondo returns to the A theme between contrasting sections.','original'),
('117.311.c.1.E',3,'Binary form has how many main sections?','["One", "Two", "Five", "Four"]'::jsonb,1,'Binary is A-B.','original'),
('117.311.c.1.F',3,'Hearing the trumpets cover the clarinets in a band piece is a problem of what?','["Key signature", "Rhythm", "Balance", "Notation"]'::jsonb,2,'Balance is the relative volume of parts.','original'),
('117.311.c.1.F',3,'When all voices in a choir sound as one unified tone, they have achieved good ___.','["Tempo", "Articulation", "Rests", "Blend"]'::jsonb,3,'Blend is unity of tone color.','original'),
('117.311.c.1.G',3,'Comparing a march and a waltz mainly contrasts which element?','["Meter and rhythmic feel", "Concert dates", "Stage lights", "Paper size"]'::jsonb,0,'Marches and waltzes use different meters.','original'),
('117.311.c.1.G',3,'The overall pitch center around which a piece is organized is its what?','["Rest", "Key", "Seat", "Page"]'::jsonb,1,'Key establishes the tonal home.','original'),
('117.311.c.1.H',2,'What helps prevent vocal strain during a long rehearsal?','["Shouting over the group", "Skipping warm-ups", "Drinking water and resting the voice when needed", "Whispering constantly"]'::jsonb,2,'Hydration and rest protect the voice.','original'),
('117.311.c.1.H',2,'A brass player feels tension in her shoulders. Which adjustment is best?','["Hold her breath", "Press harder", "Slouch deeply", "Relax the shoulders and check posture"]'::jsonb,3,'Relaxed body mechanics prevent injury.','original'),
('117.311.c.2.A',3,'A measure in 6/8 time may contain which grouping of eighth notes?','["Two groups of three", "Four groups of two", "Five groups of one", "Seven groups of three"]'::jsonb,0,'6/8 is typically felt in two beats.','original'),
('117.311.c.2.A',3,'A student writes a rhythm using an asymmetrical pattern of 2+2+3. Which meter is it?','["3/4", "7/8", "4/4", "2/4"]'::jsonb,1,'2+2+3 equals seven eighths.','original'),
('117.311.c.2.B',2,'What does allegro tell a performer?','["Play slowly", "Play very softly", "Play at a fast, lively tempo", "Pause"]'::jsonb,2,'Allegro is quick.','original'),
('117.311.c.2.B',2,'A line above a note telling the player to stress and sustain it is called what?','["A repeat bar", "A rest", "A clef", "A tenuto marking"]'::jsonb,3,'Tenuto means held.','original'),
('117.311.c.3.A',3,'A player who keeps her tone full, focused and in style as pieces grow harder is showing what?','["Increasingly mature sound", "Silence", "Weak tone", "Careless playing"]'::jsonb,0,'Tone matures with technique.','original'),
('117.311.c.3.A',3,'What most improves a flutist''s tone color?','["Tight shoulders", "Steady air support and a stable embouchure", "Rushing", "Shallow breaths"]'::jsonb,1,'Air and embouchure shape tone.','original'),
('117.311.c.3.B',3,'Which posture best supports a seated clarinetist''s breathing?','["Leaning back", "Crossing legs tightly", "Sitting tall with feet flat", "Slumping forward"]'::jsonb,2,'Open posture allows deep breaths.','original'),
('117.311.c.3.B',3,'A choir member refines her breathing so she can finish long phrases. She is refining what?','["A program note", "A ticket sale", "A seating chart", "A psychomotor skill"]'::jsonb,3,'Breath control is physical technique.','original'),
('117.311.c.3.C',3,'A drummer practices with a metronome set slowly and gradually increases the tempo. She is building what?','["Rhythmic accuracy", "A new key", "Dynamics only", "A cadenza"]'::jsonb,0,'The metronome keeps tempo steady.','original'),
('117.311.c.3.C',3,'Which habit causes uneven rhythm?','["Counting aloud", "Rushing short notes", "Using a metronome", "Subdividing"]'::jsonb,1,'Rushing distorts note values.','original'),
('117.311.c.3.D',3,'A piece has three flats in the key signature. Which notes are flatted?','["D and G", "None", "B, E and A", "F, C and G"]'::jsonb,2,'The order of flats is B, E, A, D, G.','original'),
('117.311.c.3.D',3,'When a piece changes from major to minor mode, what usually changes?','["The clef disappears", "The notes stop", "The tempo vanishes", "Some scale degrees are lowered and the mood darkens"]'::jsonb,3,'Mode changes interval patterns.','original'),
('117.311.c.3.E',3,'A trombonist adjusts her slide to match the section''s pitch. She is working on what?','["Intonation", "Seating", "Meter", "Notation"]'::jsonb,0,'Matching pitch is intonation.','original'),
('117.311.c.3.E',3,'Where should a singer breathe in a phrase?','["Randomly", "At punctuation or musical rests where the sense allows", "Never", "Mid-word"]'::jsonb,1,'Breaths follow phrase shape.','original'),
('117.311.c.3.F',3,'A student composes a short piece for her own instrument within her technical ability. This reflects what?','["Buying sheet music", "Copying a hymn", "Creating music at an appropriate level of difficulty", "Ignoring range"]'::jsonb,2,'Composition fits the player''s level.','original'),
('117.311.c.3.F',3,'Why record an original phrase after writing it?','["To avoid revising", "To skip notation", "To erase it", "To hear it and evaluate whether it works"]'::jsonb,3,'Recording supports revision.','original'),
('117.311.c.4.A',3,'A sight reader keeps a warm, controlled tone even on an unfamiliar piece. This shows what?','["Increasingly mature sound while sight reading", "Memorization only", "Careless reading", "Hesitation"]'::jsonb,0,'Tone remains consistent.','original'),
('117.311.c.4.A',3,'Which step helps maintain tone while sight reading?','["Staring at the floor", "Breathing deeply and keeping a relaxed embouchure", "Rushing every line", "Holding tension"]'::jsonb,1,'Technique supports tone.','original'),
('117.311.c.4.B',3,'A cellist sight reads while keeping her left hand relaxed and bow arm balanced. She is applying what?','["Music history", "Program notes", "Psychomotor and kinesthetic skills", "Concert dress"]'::jsonb,2,'Physical technique supports reading.','original'),
('117.311.c.4.B',3,'Sight reading with tension in the neck will most likely cause what?','["Perfect rhythm", "Faster tempo only", "Better intonation", "Poor tone and fatigue"]'::jsonb,3,'Tension hurts performance.','original'),
('117.311.c.4.C',3,'While sight reading, a student scans for slurs and accents before starting. She is preparing what?','["Correct articulation", "Costume choices", "Ticket pricing", "Audience seating"]'::jsonb,0,'Articulation markings guide performance.','original'),
('117.311.c.4.C',3,'Which method helps count a tricky rhythm in sight reading?','["Guessing", "Speaking syllables such as 1 e & a", "Skipping the measure", "Ignoring the beat"]'::jsonb,1,'Counting syllables clarifies rhythm.','original'),
('117.311.c.4.D',3,'A piece modulates from G major to D major. What should a sight reader watch for?','["A new title", "Page turns only", "A new key signature or added accidentals", "A different composer"]'::jsonb,2,'Key changes alter notes.','original'),
('117.311.c.4.D',3,'When mode changes from major to minor mid-piece, a sight reader should do what?','["Play only rests", "Stop playing", "Ignore the change", "Adjust to the new accidentals and tonal center"]'::jsonb,3,'Mode changes require attention.','original'),
('117.311.c.4.E',3,'Before singing a new melody, a student labels the first notes with numbers 1-3-5. She is using what?','["A melodic reading system", "A rhythm chart", "A bar line", "A tuner"]'::jsonb,0,'Scale-degree numbers aid reading.','original'),
('117.311.c.4.E',3,'Which is a melodic reading system?','["Dynamics", "Solfège", "Metronome", "Tempo"]'::jsonb,1,'Solfège labels pitches by syllable.','original'),
('117.311.c.4.F',3,'A sight reader follows crescendo markings and shapes phrases while reading. She is applying what?','["Rests only", "Clefs only", "Dynamics and phrasing", "Key changes only"]'::jsonb,2,'She interprets expressive markings.','original'),
('117.311.c.4.F',3,'What should a sight reader do at a phrase marking?','["Play louder always", "Play every note equally", "Stop abruptly", "Shape the line with direction and a natural release"]'::jsonb,3,'Phrasing shapes the music.','original'),
('117.311.c.4.G',3,'A singer uses tall, rounded vowels so a chord rings in tune while sight reading. She is working on what?','["Accurate intonation", "Notation", "Meter", "Tempo"]'::jsonb,0,'Vowel shape affects pitch.','original'),
('117.311.c.4.G',3,'Listening to the bass line helps the ensemble tune because the bass provides what?','["The lyrics", "A foundation for the harmony", "The meter", "The tempo only"]'::jsonb,1,'Harmony builds from the bass.','original'),
('117.311.c.5.A',3,'A student contrasts spirituals with Renaissance madrigals. She is comparing music by what?','["Instrument price", "Seat numbers", "Genre, culture and historical period", "Concert attendance"]'::jsonb,2,'Comparison covers context.','original'),
('117.311.c.5.A',3,'Which pair of styles differs mainly in culture of origin?','["Two bar lines", "Two quarter notes", "Two C majors", "Gamelan and bluegrass"]'::jsonb,3,'They come from different cultures.','original'),
('117.311.c.5.B',2,'A marching band performing at a football game shows music used for what?','["Community spirit and entertainment", "Surveying", "Cooking", "Weather forecasting"]'::jsonb,0,'Music unites communities.','original'),
('117.311.c.5.B',2,'National anthems are an example of music used to express what?','["Math facts", "Shared identity", "Rainfall", "Recipes"]'::jsonb,1,'Anthems express national identity.','original'),
('117.311.c.5.C',3,'Studying the physics of vibrating strings connects music with what subject?','["Dance only", "Painting only", "Science", "Gym only"]'::jsonb,2,'Acoustics is science.','original'),
('117.311.c.5.C',3,'Setting a poem to music connects music with what subject?','["Chemistry", "Geometry only", "Woodworking", "English language arts"]'::jsonb,3,'Text setting links to literature.','original'),
('117.311.c.5.D',2,'A person who teaches band at a high school has a music ___.','["Vocation", "Avocation", "Fine", "Hobby only"]'::jsonb,0,'Teaching is a career.','original'),
('117.311.c.5.D',2,'Which is a music-related vocation?','["Painter''s helper", "Recording studio producer", "Dishwasher only", "Lifeguard only"]'::jsonb,1,'Production is a music career.','original'),
('117.311.c.5.E',3,'Using software to correct pitch in a recording shows how technology affects what?','["Gravity", "Weather", "How music is produced", "Taxes"]'::jsonb,2,'Technology changes production.','original'),
('117.311.c.5.E',3,'Using someone else''s recording in a video without permission raises what concern?','["Rhythm", "Meter", "Tuning", "Copyright and ethical use"]'::jsonb,3,'Using music requires permission.','original'),
('117.311.c.5.F',3,'A student creates a recording and résumé of her musical experience for a scholarship audition. She is using what?','["Tools for college and career preparation", "A rest", "A key signature", "A fermata"]'::jsonb,0,'Portfolios support auditions.','original'),
('117.311.c.5.F',3,'Which is a useful college-prep tool for a musician?','["A parking pass", "A performance portfolio", "A seating chart", "A coupon"]'::jsonb,1,'A portfolio shows skills.','original'),
('117.311.c.6.A',2,'As an audience member at a recital, you should do what?','["Talk to neighbors", "Walk across the stage", "Silence your phone and stay quiet during the music", "Take calls"]'::jsonb,2,'Etiquette respects the performers.','original'),
('117.311.c.6.A',2,'As a performer, what shows concert etiquette?','["Rolling your eyes", "Texting onstage", "Leaving before the end", "Bowing or acknowledging applause with courtesy"]'::jsonb,3,'Courtesy shows professionalism.','original'),
('117.311.c.6.B',3,'A class writes criteria for judging balance, blend and intonation in a choir performance. This is what?','["Designing criteria for informed judgments", "Skipping evaluation", "Copying a score", "Random guessing"]'::jsonb,0,'Criteria guide evaluation.','original'),
('117.311.c.6.B',3,'Which evaluation applies criteria well?','["Boring", "The altos blended nicely but the tempo dragged in the second verse", "I hate it", "It was okay"]'::jsonb,1,'Specific evidence supports judgments.','original'),
('117.311.c.6.C',3,'A student sets monthly goals and checks them against recordings of her playing. She is using what?','["A seating chart", "A costume list", "A process for self-evaluation", "A ticket log"]'::jsonb,2,'Goals and recordings support growth.','original'),
('117.311.c.6.C',3,'Which tool supports personal artistic improvement?','["A bus map", "A menu", "A coupon book", "A practice journal"]'::jsonb,3,'Journals track progress.','original'),
('117.311.c.6.D',3,'A student listens to a professional recording and compares her section''s blend to it. She is doing what?','["Evaluating performance against an exemplary model", "Skipping practice", "Ignoring quality", "Avoiding listening"]'::jsonb,0,'Comparison with models guides growth.','original'),
('117.311.c.6.D',3,'After comparing to an exemplary model, what is a good next step?','["Ignore the difference", "Set a specific goal and rehearse it", "Quit", "Blame others"]'::jsonb,1,'Evaluation leads to goals.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
